            cout <= 4'b0001; 
        else
            cout <= 4'b0000; 
    end
    reg [3:0] out;
    always @(dsp_sel, sum, cout, opB, opA)
    begin
        if (dsp_sel == 2'b00)
            out <= sum[3:0]; 
        else if (dsp_sel == 2'b01)
            out <= cout; 
        else if (dsp_sel == 2'b10)
            out <= opB; 
        else if (dsp_sel == 2'b11)
            out <= opA; 
    end
endmodule

